<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { getAccountList } from '@/api/account'
import { getOrderMatrixDetail, newRequestId, queryOrderMatrix, updateOrderNote, type MatrixOrder } from '@/api/matrix'
import type { Account } from '@/types'
import { showError, showSuccess } from '@/utils'

const route=useRoute(),router=useRouter(),loading=ref(false),accounts=ref<Account[]>([]),orders=ref<MatrixOrder[]>([]),total=ref(0),page=ref(1),summary=ref<Record<string,any>>({}),dataset=ref<Record<string,any>>({}),notice=ref('')
const filter=reactive({search:String(route.query.search||''),accountId:undefined as number|undefined,orderStatus:'',deliveryStatus:String(route.query.deliveryStatus||''),refundStatus:'ALL',startDate:'',endDate:''})
const selected=ref<Record<string,any>|null>(null),detailLoading=ref(false),activeTab=ref<'overview'|'refund'|'logistics'|'timeline'|'message'>('overview'),noteSaving=ref(false),noteForm=reactive({flag:'NONE',note:''})
const totalPages=computed(()=>Math.max(1,Math.ceil(total.value/20)))
const money=(v:unknown)=>v===null||v===undefined?'—':`¥ ${Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`
const text=(v:unknown)=>v===null||v===undefined||v===''?'—':String(v)
const time=(v:unknown)=>v?new Date(String(v)).toLocaleString('zh-CN'):'—'
const label=(v?:string)=>({WAIT_BUYER_PAY:'待付款',PAID:'已付款',TO_SHIP:'待发货',SHIPPED:'已发货',COMPLETED:'已完成',PENDING:'待处理',PROCESSING:'处理中',RETRY_WAIT:'等待重试',REVIEW_REQUIRED:'需人工核对',FAILED:'失败',SUCCESS:'成功',NONE:'无退款',REQUESTED:'退款申请',APPROVED:'已同意',REJECTED:'已拒绝',DISPUTE:'争议中',FULL:'完整',PARTIAL:'部分',UNSYNCED:'未同步',READY_AUTOMATION:'可自动评价',WAITING_ORDER_STATE:'等待订单状态',LOCAL_AUTOMATION_ONLY:'仅本地提醒',UNAVAILABLE:'不可用',READ_ONLY:'只读'}[v||'']||v||'未知')
const tone=(v?:string)=>['COMPLETED','SUCCESS','FULL','SHIPPED','READY_AUTOMATION'].includes(v||'')?'good':['FAILED','REVIEW_REQUIRED','DISPUTE','REJECTED'].includes(v||'')?'bad':['PARTIAL','PROCESSING','RETRY_WAIT','REQUESTED'].includes(v||'')?'warn':'muted'
const load=async()=>{loading.value=true;try{const result=await queryOrderMatrix({search:filter.search||undefined,accountIds:filter.accountId?[filter.accountId]:undefined,orderStatus:filter.orderStatus||undefined,deliveryStatus:filter.deliveryStatus||undefined,refundStatus:filter.refundStatus,startDate:filter.startDate||undefined,endDate:filter.endDate||undefined,page:page.value,pageSize:20});orders.value=result.data?.records||[];total.value=result.data?.total||0;summary.value=result.data?.summary||{};dataset.value=result.data?.dataset||{};notice.value=result.data?.dataNotice||''}catch(e:any){showError(e.message||'订单工作台加载失败')}finally{loading.value=false}}
const apply=()=>{page.value=1;void load()}
const openDetail=async(item:MatrixOrder)=>{detailLoading.value=true;activeTab.value='overview';try{const result=await getOrderMatrixDetail(item.orderRecordId);selected.value=result.data||null;noteForm.flag=selected.value?.order?.flag||'NONE';noteForm.note=selected.value?.order?.note||''}catch(e:any){showError(e.message||'订单详情加载失败')}finally{detailLoading.value=false}}
const saveNote=async()=>{if(!selected.value?.order?.orderRecordId)return;noteSaving.value=true;try{const result=await updateOrderNote(selected.value.order.orderRecordId,{requestId:newRequestId('order-note'),flag:noteForm.flag,note:noteForm.note});selected.value.order=result.data?.order||selected.value.order;showSuccess('订单备注已保存');await load()}finally{noteSaving.value=false}}
const openMessage=()=>{const order=selected.value?.order;if(!order)return;router.push({path:'/messages',query:{accountId:String(order.accountId),sessionId:order.sessionId||'',buyerId:order.buyerId||''}})}
onMounted(async()=>{const result=await getAccountList();accounts.value=result.data?.accounts||[];void load()})
</script>

<template>
  <main class="workbench order-matrix" :aria-busy="loading">
    <header class="workbench__header"><div><h1>订单与售后</h1><p>跨店查询履约、退款、物流和评价；平台事实与本地处理状态分开展示。</p></div><button class="workbench__btn" :disabled="loading" @click="load">{{ loading?'刷新中':'刷新' }}</button></header>
    <section class="order-matrix__metrics"><article><span>筛选订单</span><strong>{{ summary.orderCount??'—' }}</strong><small>当前结果范围</small></article><article><span>成交金额</span><strong>{{ money(summary.gmv) }}</strong><small>已知金额 {{ summary.knownAmountCount??'—' }} 单</small></article><article><span>待履约</span><strong>{{ summary.pendingDeliveryCount??'—' }}</strong><small>待处理 / 重试中</small></article><article><span>退款处理中</span><strong>{{ summary.refundingCount??'—' }}</strong><small>已知退款 {{ money(summary.refundAmount) }}</small></article><article><span>数据覆盖</span><strong>{{ label(summary.coverageStatus) }}</strong><small>{{ dataset.coveredAccountCount??'—' }}/{{ dataset.accountCount??'—' }} 个店铺</small></article></section>
    <div class="order-matrix__notice"><strong>数据说明</strong><span>{{ notice||'订单金额或退款未采集时保持为空。' }}</span><time>最近成功 {{ time(dataset.lastSuccessTime) }}</time></div>
    <section class="workbench__card order-matrix__panel"><div class="order-matrix__toolbar"><input v-model="filter.search" class="workbench__input" placeholder="订单号、买家、商品或运单号" @keyup.enter="apply"><select v-model="filter.accountId" class="workbench__select" @change="apply"><option :value="undefined">全部可见店铺</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.accountNote||a.unb }}</option></select><select v-model="filter.deliveryStatus" class="workbench__select" @change="apply"><option value="">全部履约状态</option><option value="PENDING">待履约</option><option value="PROCESSING">处理中</option><option value="RETRY_WAIT">等待重试</option><option value="REVIEW_REQUIRED">人工核对</option><option value="FAILED">失败</option><option value="SUCCESS">成功</option></select><select v-model="filter.refundStatus" class="workbench__select" @change="apply"><option value="ALL">全部退款状态</option><option value="NONE">无退款</option><option value="REQUESTED">退款申请</option><option value="PROCESSING">处理中</option><option value="APPROVED">已同意</option><option value="REJECTED">已拒绝</option><option value="DISPUTE">争议中</option></select><input v-model="filter.startDate" class="workbench__input" type="date" aria-label="开始日期"><input v-model="filter.endDate" class="workbench__input" type="date" aria-label="结束日期"><button class="workbench__btn workbench__btn--primary" @click="apply">查询</button></div>
      <div class="order-matrix__table"><table><thead><tr><th>订单 / 店铺</th><th>商品 / 买家</th><th>金额</th><th>订单状态</th><th>履约</th><th>退款</th><th>数据证据</th><th></th></tr></thead><tbody><tr v-for="item in orders" :key="item.orderRecordId" :class="{exception:item.hasException}" @click="openDetail(item)"><td><strong>{{ item.orderId }}</strong><small>{{ item.accountName||`店铺 ${item.accountId}` }}</small></td><td><strong>{{ item.goodsTitle||item.goodsId||'商品未知' }}</strong><small>{{ item.buyerName||'买家未知' }}</small></td><td><strong>{{ money(item.amount) }}</strong><small>{{ item.amount==null?'金额未采集':item.currency||'CNY' }}</small></td><td><span :class="['status',tone(item.orderStatus)]">{{ label(item.orderStatus) }}</span><small>{{ time(item.createdTime) }}</small></td><td><span :class="['status',tone(item.deliveryStatus)]">{{ label(item.deliveryStatus) }}</span></td><td><span :class="['status',tone(item.refundStatus)]">{{ label(item.refundStatus) }}</span></td><td><strong>{{ item.dataSource||'NONE' }}</strong><small>{{ label(item.coverageStatus) }} · {{ time(item.lastSyncedTime) }}</small></td><td><button class="row-action" @click.stop="openDetail(item)">详情</button></td></tr></tbody></table><div v-if="!loading&&!orders.length" class="order-matrix__empty">当前范围没有订单记录。</div></div><footer class="order-matrix__pagination"><span>共 {{ total }} 条</span><div><button :disabled="page<=1" @click="page--;load()">上一页</button><b>{{ page }} / {{ totalPages }}</b><button :disabled="page>=totalPages" @click="page++;load()">下一页</button></div></footer></section>
    <div v-if="selected||detailLoading" class="order-drawer__backdrop" @click.self="selected=null"><aside class="order-drawer" role="dialog" aria-modal="true" aria-labelledby="order-title"><div v-if="detailLoading" class="order-drawer__loading">正在读取订单事实…</div><template v-else-if="selected"><header><div><p>{{ selected.order.accountName||`店铺 ${selected.order.accountId}` }}</p><h2 id="order-title">订单 {{ selected.order.orderId }}</h2><small>{{ selected.order.goodsTitle||selected.order.goodsId||'商品未知' }} · {{ selected.order.buyerName||'买家未知' }}</small></div><button aria-label="关闭" @click="selected=null">×</button></header><nav><button v-for="tab in [{k:'overview',n:'概览'},{k:'logistics',n:'物流'},{k:'refund',n:`退款 ${selected.refunds?.length||0}`},{k:'message',n:`消息 ${selected.messages?.length||0}`},{k:'timeline',n:`时间线 ${selected.timeline?.length||0}`} ]" :key="tab.k" :class="{active:activeTab===tab.k}" @click="activeTab=tab.k as any">{{ tab.n }}</button></nav><div class="order-drawer__body"><template v-if="activeTab==='overview'"><section class="order-facts"><div><span>金额</span><strong>{{ money(selected.order.amount) }}</strong></div><div><span>订单状态</span><strong>{{ label(selected.order.orderStatus) }}</strong></div><div><span>履约状态</span><strong>{{ label(selected.order.deliveryStatus) }}</strong></div><div><span>评价能力</span><strong>{{ label(selected.capabilities?.rating?.status) }}</strong></div></section><section class="drawer-card"><h3>本地协作备注</h3><label>旗帜<select v-model="noteForm.flag" class="workbench__select"><option v-for="f in ['NONE','RED','ORANGE','YELLOW','GREEN','BLUE','PURPLE']" :key="f" :value="f">{{ f }}</option></select></label><label>备注<textarea v-model="noteForm.note" class="workbench__textarea" maxlength="1000"></textarea></label><button class="workbench__btn workbench__btn--primary" :disabled="noteSaving" @click="saveNote">保存备注</button></section><section class="drawer-card"><h3>能力边界</h3><div class="capability-grid"><article v-for="(cap,key) in selected.capabilities" :key="key"><strong>{{ key }}</strong><span :class="['status',tone(cap.status)]">{{ label(cap.status) }}</span><p>{{ cap.reason||cap.source||'按当前订单状态动态判断' }}</p></article></div></section></template><template v-else-if="activeTab==='logistics'"><section class="drawer-card"><h3>物流事实</h3><dl><div><dt>物流公司</dt><dd>{{ text(selected.order.logisticsCompanyName) }}</dd></div><div><dt>运单号</dt><dd>{{ text(selected.order.trackingNumber) }}</dd></div><div><dt>物流状态</dt><dd>{{ text(selected.order.logisticsStatus) }}</dd></div><div><dt>最近事件</dt><dd>{{ text(selected.order.logisticsLastEvent) }}</dd></div></dl><p>系统不在没有平台确认的情况下伪造实物发货成功。</p></section></template><template v-else-if="activeTab==='refund'"><section v-if="selected.refunds?.length" class="drawer-card risk-list"><article v-for="refund in selected.refunds" :key="refund.refundCaseId"><strong>{{ refund.type||'退款' }} · {{ money(refund.requestedAmount) }}</strong><span>{{ label(refund.platformStatus) }}</span><p>{{ refund.reason||'未同步原因' }}</p><small>截止 {{ time(refund.decisionDeadline) }} · {{ refund.source }} · {{ label(refund.coverageStatus) }}</small></article></section><div v-else class="order-matrix__empty">当前记录没有已同步退款案例。</div></template><template v-else-if="activeTab==='message'"><section class="drawer-card message-list"><article v-for="(m,index) in selected.messages" :key="index"><strong>{{ m.senderName||m.senderId||'未知发送者' }}</strong><p>{{ m.content||m.msgContent||'[非文本消息]' }}</p><small>{{ time(m.messageTime||m.storedAt) }}</small></article></section></template><template v-else><ol class="timeline"><li v-for="(event,index) in selected.timeline" :key="index"><i></i><div><strong>{{ event.eventType||event.description }}</strong><p>{{ event.outcomeState||event.operationStatus }} · {{ event.dataSource||'LOCAL' }}</p><small>{{ time(event.createdTime||event.createdTimeEpochMs) }}</small></div></li></ol></template></div><footer><button class="workbench__btn" @click="openMessage">查看买家会话</button><button class="workbench__btn workbench__btn--primary" @click="selected=null">完成查看</button></footer></template></aside></div>
  </main>
</template>
<style scoped src="./orders.css"></style>
<style scoped>
@media (max-width: 767px) {
  .order-matrix__metrics { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); overflow: visible; }
  .order-matrix__metrics article { min-width: 0; }
}
</style>
